import java.util.Scanner;

public class Main {
    public static long getNumber(Scanner sc) {
        long num = 0;
        int c;
        // Skip non-digit characters
        do {
            c = sc.next().charAt(0);
        } while (c < 33);
        // Read number
        while (c > 33) {
            num = num * 10 + (c - '0');
            if (sc.hasNext()) {
                c = sc.next().charAt(0);
            } else {
                break;
            }
        }
        return num;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x_val = getNumber(sc);
        long y_val = getNumber(sc);
        long total = getNumber(sc);

        long numerator = 0;
        long denominator = 1;

        for (long index = 1; index <= total; ++index) {
            long p = x_val * index / y_val;
            long q = p + 1;
            long diff = index * Math.abs(x_val * denominator - numerator * y_val);
            long t1 = denominator * Math.abs(x_val * index - y_val * p);
            long t2 = denominator * Math.abs(x_val * index - y_val * q);
            if (t1 < diff) {
                numerator = p;
                denominator = index;
                diff = t1;
            }
            if (t2 < diff) {
                numerator = q;
                denominator = index;
                diff = t2;
            }
        }
        System.out.println(numerator + "/" + denominator);
        sc.close();
    }
}
